package nhom10.phonenest.mapper;
import lombok.RequiredArgsConstructor; import nhom10.phonenest.dto.DonHangDto; import nhom10.phonenest.entity.*; import nhom10.phonenest.repository.*; import org.springframework.stereotype.Component; import java.util.*;
@Component @RequiredArgsConstructor public class DonHangMapper{ private final ThanhToanRepository thanhToanRepository; private final YeuCauDoiTraRepository doiTraRepository; private final HuyDonHangRepository huyRepository;
 public DonHangDto toDto(DonHang d){List<DonHangDto.Dong> ds=d.getChiTiet().stream().map(c->new DonHangDto.Dong(c.getPhienBan().getSanPham().getMaSanPham(),c.getPhienBan().getMaPhienBan(),c.getTenSanPham()+" - "+c.getTenPhienBan(),c.getHinhAnh(),c.getSoLuong(),c.getDonGia())).toList(); var payments=thanhToanRepository.findByDonHangMaDonHangOrderByNgayTaoDesc(d.getMaDonHang()); var payment=nhom10.phonenest.util.OrderPaymentPolicy.effective(payments); var pt=payment==null?null:payment.getPhuongThuc(); var info=payment==null?null:new DonHangDto.ThanhToanInfo(pt,payment.getTrangThai(),payment.getSoTien(),payment.getMaGiaoDich(),payment.getMaGiaoDichNganHang(),payment.getMaGiaoDichMoMo(),payment.getNgayThanhToan());String dt=doiTraRepository.findByDonHangMaDonHangOrderByNgayTaoDesc(d.getMaDonHang()).stream().findFirst().map(x->x.getTrangThai().name()).orElse(null);String huy=huyRepository.findById(d.getMaDonHang()).map(h->h.getGhiChu()==null||h.getGhiChu().isBlank()?h.getLyDo():h.getLyDo()+": "+h.getGhiChu()).orElse(null);return new DonHangDto(d.getMaDonHang(),d.getKhachHang().getMaKh(),d.getKhuyenMai()==null?null:d.getKhuyenMai().getMaKm(),d.getKhuyenMaiVanChuyen()==null?null:d.getKhuyenMaiVanChuyen().getMaKm(),d.getNgayMua(),pt,d.getTrangThai(),d.getTamTinh(),d.getGiamGia(),d.getPhiVanChuyen(),d.getGiamPhiVanChuyen(),d.getTongThanhToan(),d.getDiaChiGiaoHang(),d.getNgayCapNhat(),d.getNgayGiao(),d.getKhachHang().getHoTen(),d.getTenNguoiNhan(),d.getSoDienThoaiNhan(),dt,huy,d.getNgayKhachXacNhan(),d.getNgayKhachXacNhan()==null?null:d.getKhachHang().getHoTen(),ds,d.getPhiKhaiGia(),d.getPhuPhiCod(),d.getNgayGiaoDuKienTu(),d.getNgayGiaoDuKienDen(),info,!nhom10.phonenest.util.OrderPaymentPolicy.canEditQuantity(payments));}
}
